"""Archive exact finished current-round journal tail under the same main flock."""
import collections,hashlib,json,os,subprocess,sys
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=Path(__file__).resolve().parent;sys.path.insert(0,str(R));from common import reg,sha,put,rel
start=json.loads((R/'startup.json').read_text());ctx=json.loads((R/'context.json').read_text());pid=start['branch_lock_broker_pid'];ino=(ROOT/'research/automation/branch.lock').stat().st_ino;assert any('FLOCK' in x and x.split()[4]==str(pid) and int(x.split()[5].split(':')[-1])==ino for x in Path('/proc/locks').read_text().splitlines())
main=ROOT/'research/automation/registry.jsonl';fragment=R/'registry_records.jsonl';assert not fragment.exists();prefix=subprocess.check_output(['git','show',start['base_commit']+':research/automation/registry.jsonl'],cwd=ROOT);raw=main.read_bytes();assert raw.startswith(prefix) and hashlib.sha256(prefix).hexdigest()==ctx['main_registry_sha256_before_reserve'];tail=raw[len(prefix):];events=[json.loads(x) for x in tail.splitlines()];batch=sum([json.loads((R/name).read_text()) for name in ['batch.json','forward_batch.json','candidate_batch.json','l4h02_batch.json','fewm_batch.json']],[]);assert len(batch)==32 and len(events)==64 and {x['fingerprint'] for x in batch}=={x['fingerprint'] for x in events}
for row in batch:
 es=[x for x in events if x['fingerprint']==row['fingerprint']];assert len(es)==2 and es[0]['status']=='reserved' and es[1]['result_available'] and es[1]['status'] in ['passed','rejected']
canon=lambda x:json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False)
index_before=reg.read_records(main);events_before=reg.read_events(main);multi_before=collections.Counter(canon(x) for x in events_before);assert len(index_before)==ctx['registry_ids']+32 and len(events_before)==ctx['registry_events']+64
fragment.write_bytes(tail);tmp=main.with_suffix('.research_restore.tmp');tmp.write_bytes(prefix);os.replace(tmp,main)
index_after=reg.read_records(main);events_after=reg.read_events(main);assert index_after==index_before and collections.Counter(canon(x) for x in events_after)==multi_before and main.read_bytes()==prefix and hashlib.sha256(main.read_bytes()+fragment.read_bytes()).hexdigest()==hashlib.sha256(raw).hexdigest()
assert all(sha(ROOT/p)==h for p,h in ctx['ledger_fragments_before'].items())
put(R/'registry_fragment_layout.json',{'passed':True,'recorded_utc':datetime.now(timezone.utc).isoformat(),'main_path':rel(main),'main_prefix_sha256':sha(main),'main_prefix_bytes':len(prefix),'fragment_path':rel(fragment),'fragment_sha256':sha(fragment),'fragment_bytes':len(tail),'original_append_stream_sha256':hashlib.sha256(raw).hexdigest(),'prefix_plus_fragment_sha256':hashlib.sha256(prefix+tail).hexdigest(),'full_index_sha256':hashlib.sha256(canon(index_after).encode()).hexdigest(),'full_event_multiset_sha256':hashlib.sha256(canon(sorted(multi_before.items())).encode()).hexdigest(),'before_events':ctx['registry_events'],'after_events':len(events_after),'before_IDs':ctx['registry_ids'],'after_IDs':len(index_after),'current_round_events':64,'current_round_finished_IDs':32,'physical_main_exact_original_prefix':True,'all_old_fragments_unchanged':True,'logical_records_and_all_event_contents_equal_before_after':True,'physical_event_iteration_order_equal':events_before==events_after,'iteration_order_explanation':'Physical fragment iterationorder maydiffer;exacteventcontent/multiplicity andtimestampmergedindex identical.','no_history_or_current_result_removed':True,'canonical_fragment_aware_reader':'research/automation/registry.py _ledger_paths/read_events/read_records'})
print(json.dumps({'passed':True,'events':64,'IDs':32,'total_events':len(events_after),'total_IDs':len(index_after),'fragment_bytes':len(tail),'old_main_prefix_bytes':len(prefix)}))
